CREATE TABLE IF NOT EXISTS `${PROJECT_ID}.${DATASET}.tax_calculations` (calculation_id STRING NOT NULL,case_id STRING NOT NULL,assessment_year STRING,rules_version STRING,regime STRING,input_hash STRING,gross_income NUMERIC,total_deductions NUMERIC,taxable_income NUMERIC,tax_liability NUMERIC,tds NUMERIC,estimated_balance NUMERIC,created_at TIMESTAMP) PARTITION BY DATE(created_at) CLUSTER BY assessment_year,regime;
